INSERT INTO public.cases (case_id, title, symptom, topology_note, show_output, expected_fault, osi_layer, concept, severity, next_command, recommended_fix, version)
VALUES ('NET-001', 'VLAN missing - Scenario 1', 'Switch does not have the required VLAN configured.', 'Typical Cisco Packet Tracer topology involving a vlan-related fault. The exact devices and addressing should be inferred only from the provided case evidence.', 'show vlan brief. Use the returned configuration/status as the primary evidence. Also compare the affected device/interface with the neighboring device and the expected topology. Do not assume the fault without matching evidence.', 'VLAN missing. Create the required VLAN and verify membership.', 'Layer 2', 'VLAN', 'Medium', 'show vlan brief', '1) Configure the VLAN on the switch and assign the required access ports. 2) Verify the configuration with show vlan brief. 3) Test the affected communication path. 4) Confirm that no unrelated configuration was changed.', 1)
ON CONFLICT (case_id) DO UPDATE SET title = EXCLUDED.title, symptom = EXCLUDED.symptom, show_output = EXCLUDED.show_output, expected_fault = EXCLUDED.expected_fault, recommended_fix = EXCLUDED.recommended_fix;

