INSERT INTO public.cases (case_id, title, symptom, topology_note, show_output, expected_fault, osi_layer, concept, severity, next_command, recommended_fix, version)
VALUES ('NET-006', 'Access port in wrong VLAN - Scenario 1', 'End device is connected to a port assigned to the wrong VLAN.', 'Typical Cisco Packet Tracer topology involving a vlan-related fault. The exact devices and addressing should be inferred only from the provided case evidence.', 'show vlan brief. Use the returned configuration/status as the primary evidence. Also compare the affected device/interface with the neighboring device and the expected topology. Do not assume the fault without matching evidence.', 'Access port in wrong VLAN. Move the access interface into the correct VLAN.', 'Layer 2', 'VLAN', 'Low', 'show vlan brief', '1) Configure the interface as access mode and assign the intended VLAN. 2) Verify the configuration with show vlan brief. 3) Test the affected communication path. 4) Confirm that no unrelated configuration was changed.', 1)
