INSERT INTO public.cases (case_id, title, symptom, topology_note, show_output, expected_fault, osi_layer, concept, severity, next_command, recommended_fix, version)
VALUES ('NET-011', 'Trunk not configured - Scenario 1', 'Multiple VLANs cannot cross a link because the link is operating as an access port.', 'Typical Cisco Packet Tracer topology involving a vlan-related fault. The exact devices and addressing should be inferred only from the provided case evidence.', 'show interfaces trunk. Use the returned configuration/status as the primary evidence. Also compare the affected device/interface with the neighboring device and the expected topology. Do not assume the fault without matching evidence.', 'Trunk not configured. Configure the inter-switch/router link as a trunk.', 'Layer 2', 'VLAN', 'High', 'show interfaces trunk', '1) Set trunk mode and verify allowed VLANs. 2) Verify the configuration with show interfaces trunk. 3) Test the affected communication path. 4) Confirm that no unrelated configuration was changed.', 1)
