INSERT INTO public.cases (case_id, title, symptom, topology_note, show_output, expected_fault, osi_layer, concept, severity, next_command, recommended_fix, version)
VALUES ('NET-071', 'Wrong default gateway - Scenario 1', 'Host cannot reach networks outside its local subnet.', 'Typical Cisco Packet Tracer topology involving a gateway-related fault. The exact devices and addressing should be inferred only from the provided case evidence.', 'ipconfig /all. Use the returned configuration/status as the primary evidence. Also compare the affected device/interface with the neighboring device and the expected topology. Do not assume the fault without matching evidence.', 'Wrong default gateway. Compare host gateway with the router interface address.', 'Layer 3', 'Gateway', 'High', 'ipconfig /all', '1) Configure the correct default gateway on the host. 2) Verify the configuration with ipconfig /all. 3) Test the affected communication path. 4) Confirm that no unrelated configuration was changed.', 1)
